'use strict';
// Prompt-library selection is stage-local. Only the original rule-bearing tools
// may load the corresponding rule module, after an explicit, reviewable switch.
const pgBase={configPanel,modalContent,handleAction,closeModal,mappingEditor,configurationFragment,seedConfig};
const PG_IDS=TOOLS.map(t=>t.id).filter(id=>!['extract','word'].includes(id));
const PG_ROOT_DEFAULTS=Object.fromEntries(PG_IDS.map(id=>{const c=twEmptyDraft(id).config;seedConfig(id,c);if(awDefaults[id])c.stages=structuredClone(awDefaults[id]);return[id,structuredClone(c)];}));
// Upgrade only untouched preparation defaults. Saved personal edits, imports and
// execution snapshots must retain their own text and library identity.
seedConfig=function(id,c){pgBase.seedConfig(id,c);if(!PG_IDS.includes(id)||c!==state.work[id]?.config||state.work[id]?.taskId)return c;for(const [key,label] of PROMPT_STAGES[id]){const s=c.stages[key],d=PG_ROOT_DEFAULTS[id].stages[key];if(!s||s.customized||s.origin!=='system'||s.pgChoice&&s.pgChoice!=='system'||s.template!==d.template)continue;const initial='请依据所选资料，'+tool(id).desc+'。保留原文引用；未提取到的内容如实标注，不补充资料外事实。',generic='请依据已提供资料完成'+label+'，说明依据、资料不足与需进一步核验事项，不推断资料外事实。';if([d.content,d.content.replace('未取得','未提取到'),initial,generic].includes(s.content)){s.content=d.content;s.pgChoice='system';s.scope='public';s.category='system';}}return c;};
const PG_LABELS={timeline:{timeline:['事项提取','提取事项日期、内容及原文来源。']},theme:{extract:['资料要点','逐份摘录事项、单位、金额、日期和原文依据。'],summarize:['主题归纳','按审计关注内容汇总同类事项，保留差异及来源。']},meeting:{regular:['会议与议题','整理会议决策、金额、人员和落实要求。'],risk:['后续风险分析','生成风险报告时使用，不随议题整理自动执行。']},risk:{risk:['风险分析','选择提示词后，勾选本次要检查的风险点。']},contract:{compliance:['合同合规分析','按本次检查要求核对合同条款。'],information:['合同信息提取','提取合同基本信息及对应原文。']},bidding:{tender:['招标文件分析','核查招标条件、评审标准及相关规则。'],bid:['投标文件分析','核查投标响应及相关规则。'],joint:['联合分析','结合招投标资料对照检查。']},prepaid:{agreement:['计费约定提取','从合同中提取计费依据、费率及支付约定。'],calculation:['费用计算','依据提取到的约定和本次计费基数计算费用。']},engineering:{duplicate:['重复项目分析','设置重复项目的提取和比较要求。'],parent:['主子项目分析','设置主子项目关系的识别要求。']},association:{compare:['两表对比','按对应字段、评分及判定规则比较两张表。']}};
function pgActive(){return state.view==='tool'&&PG_IDS.includes(state.toolId);}
function pgDefs(id=state.toolId){return (PROMPT_STAGES[id]||[]).filter(([key])=>id!=='bidding'||(currentTask()?.modes||ws().modes).includes(key));}
function pgTitle(id,key){return PG_LABELS[id]?.[key]?.[0]||PROMPT_STAGES[id].find(s=>s[0]===key)?.[1]||'分析';}
function pgRelated(id,key,raw={},stage={}){const cfg=raw||{};
 if(id==='risk'){const nodes=Array.isArray(cfg.riskNodes)?structuredClone(cfg.riskNodes):[];return{riskNodes:nodes,...(Array.isArray(cfg.checks)?{checks:[...cfg.checks]}:Array.isArray(cfg.selected_risk_ids)?{checks:nodes.filter(n=>cfg.selected_risk_ids.includes(n.id)).map(n=>n.name)}:{})};}
 if(id==='engineering')return{engineering:{[key]:structuredClone(cfg.engineering?.[key]||PG_ROOT_DEFAULTS.engineering.engineering[key])}};
 if(id==='association')return{association:structuredClone(cfg.association||PG_ROOT_DEFAULTS.association.association)};
 if(id==='bidding'){const source=cfg.bidding?.[key]||stage.promptConfig?.bidding?.[key]||stage.ruleConfig||{},rules=source.rules||cfg.rules||stage.rules||[],ids=source.ruleIds||stage.ruleIds||cfg.rule_ids||cfg[key==='tender'?'bidding_rules':key==='bid'?'tender_rules':'joint_rules']||[];return{bidding:{[key]:{...structuredClone(source),rules:structuredClone(Array.isArray(rules)?rules:[]),ruleIds:[...(Array.isArray(ids)?ids:[])],...(cfg.template_id?{templateId:cfg.template_id}:{})}}};}
 return null;
}
function pgCaptureRelated(id,key,c){if(id==='risk')return{riskNodes:structuredClone(c.riskNodes),checks:[...c.checks]};if(id==='engineering')return{engineering:{[key]:structuredClone(c.engineering[key])}};if(id==='association')return{association:structuredClone(c.association)};if(id==='bidding')return pgRelated(id,key,c.stages[key].promptConfig,c.stages[key]);return null;}
const PG_GROUPS=[['public','scenario','公共提示词 / 场景提示词'],['public','function','公共提示词 / 功能提示词'],['public','system','公共提示词 / 系统提示词'],['org','', '机构提示词'],['personal','','个人提示词']];
function pgScope(t){const source=t.scope||t.spaceType||t.space_type||t.origin;return ['public','公共提示词','system'].includes(source)?'public':['org','organization','机构提示词'].includes(source)?'org':'personal';}
function pgCategory(t){const category=t.category||t.categoryType||t.category_type;return ['scenario','场景提示词'].includes(category)?'scenario':['function','功能提示词'].includes(category)?'function':'system';}
function pgLibrary(id,key){const def=PG_ROOT_DEFAULTS[id].stages[key],type=PROMPT_STAGES[id].find(d=>d[0]===key)[2],items=[{value:'system',name:def.template,content:def.content,origin:'system',scope:'public',category:'system',isDefault:true,backendId:def.backendId||null,related:pgRelated(id,key,PG_ROOT_DEFAULTS[id],def)}];for(const t of state.templates){const functionType=t.functionType||t.function_type,typeMatch=functionType===type;if(t.deleted||t.status==='disabled'||t.canUse===false||t.toolId&&t.toolId!==id||!t.toolId&&!typeMatch||functionType&&!typeMatch||t.stage&&t.stage!==key)continue;const saved=t.config?.stages?.[key],content=saved?.content||(t.stage===key||typeMatch||PROMPT_STAGES[id][0][0]===key?t.prompt||t.content:null);if(typeof content!=='string'||!content.trim())continue;const scope=pgScope(t),category=scope==='public'?pgCategory(t):'';items.push({value:'p:'+t.id,name:t.name,content,origin:scope==='public'?'system':scope,scope,category,backendId:t.backendId??t.backend_id??null,related:pgRelated(id,key,t.promptConfig||t.config||{},saved||t)});}return items;}
function pgChoice(id,key,stage){const items=pgLibrary(id,key),item=items.find(r=>r.value===stage.pgChoice&&r.content===stage.content)||items.find(r=>r.name===stage.template&&r.content===stage.content&&r.scope===pgScope(stage)&&(r.scope!=='public'||r.category===pgCategory(stage)));return !stage.customized&&item?item.value:'current';}
function pgSelect(id,key,stage,attrs=''){const selected=pgChoice(id,key,stage),items=pgLibrary(id,key),choice=items.find(i=>i.value===selected),source=choice||stage,scope=pgScope(source),category=scope==='public'?pgCategory(source):'',path=PG_GROUPS.find(g=>g[0]===scope&&g[1]===category)?.[2]||'本次提示词';return '<select '+attrs+' aria-label="'+E(pgTitle(id,key)+'提示词')+'">'+(selected==='current'?'<option value="current" selected>'+E((stage.template||'本次提示词')+(stage.customized?' · 本次已调整':' · 本次保留'))+'</option>':'')+PG_GROUPS.map(([group,cat,label])=>{const entries=items.filter(i=>i.scope===group&&i.category===cat);return '<optgroup label="'+label+'">'+(entries.length?entries.map(i=>'<option value="'+E(i.value)+'" '+(selected===i.value?'selected':'')+'>'+E(i.name+(i.isDefault?' · 系统默认':''))+'</option>').join(''):'<option disabled>暂无适用提示词</option>')+'</optgroup>';}).join('')+'</select><small class="pg-source-path">'+E(path)+(stage.customized?' · 本次已调整':'')+'</small>';}
function pgRuleList(stage){const rules=stage.promptConfig?.bidding?.[stage.pgStage]||stage.ruleConfig;if(!rules)return '';const ids=rules.ruleIds||[],meta=rules.rules||[],entries=meta.length?meta.map(r=>typeof r==='string'?r:r.name||r.label||r.title||r.id):ids;return entries.length?'<details class="pg-rule-list"><summary>检查规则 · '+entries.length+' 项</summary><ul>'+entries.map(r=>'<li>'+E(r)+'</li>').join('')+'</ul></details>':'';}
function pgStageCard(id,key,c,locked){const stage=c.stages[key],help=id==='timeline'?'':PG_LABELS[id]?.[key]?.[1]||'',related=['risk','engineering','association','bidding'].includes(id),business=id==='theme'?key==='extract'?'资料要点提示词':'主题归纳提示词':pgTitle(id,key)+'提示词';return '<section class="pg-stage-card" data-pg-stage-card="'+key+'"><div class="pg-stage-heading"><h3>'+business+'</h3>'+A(locked?'查看':'编辑','aw-prompt','data-stage="'+key+'"')+'</div>'+(help?'<p class="pg-stage-help">'+E(help)+'</p>':'')+'<label class="pg-select-label">'+(locked?'本次使用的提示词':'从提示词库选择')+pgSelect(id,key,stage,'data-pg-prompt="'+key+'" '+(locked?'disabled':''))+'</label><p class="pg-prompt-preview" title="'+E(stage.content)+'">'+E(stage.content)+'</p>'+(stage.customized?'<span class="pg-custom-note">本次已调整</span>':'')+(related?'<p class="pg-rule-note">'+E(id==='risk'?'配套风险点在下方勾选。':id==='bidding'?'随提示词载入本环节的检查规则。':'切换提示词会载入本项配套字段与判定规则。')+'</p>':'')+(id==='bidding'?pgRuleList({...stage,pgStage:key}):'')+'</section>';}
configPanel=function(){const html=pgBase.configPanel();if(!pgActive())return html;const root=document.createElement('div');root.innerHTML=html;const panel=root.querySelector('aside');if(!panel)return html;const c=currentTask()?.config||ws().config,locked=!!currentTask(),id=state.toolId,body=panel.querySelector('.ew-config-body')||panel;panel.classList.add('pg-config');if(id==='theme'&&!locked){const st=c.stages.summarize,generic='请依据已提供资料完成'+PROMPT_STAGES.theme.find(d=>d[0]==='summarize')[1]+'，说明依据、资料不足与需进一步核验事项，不推断资料外事实。';if(st&&!st.customized&&st.origin!=='personal'&&st.content===generic)st.content=PG_ROOT_DEFAULTS.theme.stages.summarize.content;}if(id==='timeline')panel.querySelectorAll('.aw-scope-tip').forEach(n=>n.remove());
 panel.querySelectorAll('.aa-scheme,.th-scheme,.th-scheme-management,[data-aa-details=scheme]').forEach(n=>n.remove());
 panel.querySelectorAll('select[data-config=template]').forEach(select=>select.closest('.config-section,.ew-config-section')?.remove());
 const nodes=[...panel.querySelectorAll('.aa-rule,.th-rule,.aw-stage,.stage-line')],defs=pgDefs();nodes.forEach((node,i)=>{const key=node.querySelector('[data-stage]')?.dataset.stage||defs[i]?.[0];if(key&&c.stages[key])node.outerHTML=pgStageCard(id,key,c,locked);});
 if(!nodes.length&&defs.length){const holder=document.createElement('div');holder.className='pg-stage-list';holder.innerHTML=defs.map(([key])=>pgStageCard(id,key,c,locked)).join('');body.append(holder);}
 panel.querySelectorAll('[data-action=aw-save-scheme],[data-action=save-template],[data-action=aw-import-config],[data-action=v2-export-config],[data-action=v2-config-json]').forEach(n=>n.remove());panel.querySelectorAll('.config-toolbar:empty,.ew-template-actions:empty,.aw-more').forEach(n=>n.remove());if(id==='risk'&&!c.riskNodes.length){const note=panel.querySelector('.aa-empty-small');if(note)note.textContent=locked?'本次提示词未配置风险点。':'该提示词未配置风险点，请点击“管理风险点”添加检查项。';}return root.innerHTML;};
function pgStageFrom(item,id,key){return{template:item.name,content:item.content,functionType:PROMPT_STAGES[id].find(d=>d[0]===key)[2],origin:item.origin,scope:item.scope,category:item.category,backendId:item.backendId??null,customized:false,pgChoice:item.value,...(item.related?{promptConfig:structuredClone(item.related)}:{})};}
function pgApplyRelated(c,id,key,related){if(!related)return;if(id==='risk'){c.riskNodes=structuredClone(related.riskNodes||[]);const names=c.riskNodes.map(n=>n.name);c.checks=(related.checks||c.checks||[]).filter(n=>names.includes(n));}if(id==='engineering')c.engineering[key]=structuredClone(related.engineering[key]);if(id==='association')c.association=structuredClone(related.association);if(id==='bidding'){const rules=related.bidding?.[key];c.stages[key].promptConfig=structuredClone(related);c.stages[key].ruleIds=[...(rules?.ruleIds||[])];}}
function pgSync(c,id){const first=pgDefs(id)[0]?.[0]||PROMPT_STAGES[id][0][0];c.prompt=c.stages[first].content;}
function pgImpact(id,key){return id==='risk'?'风险点清单及本次勾选':id==='engineering'?pgTitle(id,key)+'的字段、权重、规则和阈值':id==='association'?'两表字段匹配、评分、硬规则及比较参数':id==='bidding'?pgTitle(id,key)+'的检查规则':'';}
function pgOpen(stage,secondary=false){const c=currentTask()?.config||ws().config,drafts=structuredClone(c.stages);if(secondary)drafts.risk=structuredClone(currentTask().riskStageDraft||currentTask().riskReportConfig||c.stages.risk);openModal('aw-prompt',{pg:true,stage,drafts,draft:drafts[stage],initial:JSON.stringify(drafts),secondary,pgPatches:{}});}
function pgEditor(p){
 const id=state.toolId,key=p.stage,locked=!!currentTask()&&!p.secondary,defs=pgDefs().filter(([k])=>!p.secondary||k==='risk');
 const subtitle=p.secondary?'仅用于下一次风险报告，已完成的会议议题保持不变。':locked?'执行时使用的提示词，只读保留。':'';
 const editorHeading='<div class="pg-editor-label"><label for="prompt-editor">提示词内容 <b class="red">*</b></label><span>'+ (locked?'只读':p.secondary?'下次风险分析':'本次生效')+'</span>'+(!locked?A('恢复默认提示词','aw-prompt-reset'):'')+'</div>';
 return modalFrame(locked?'查看本次提示词':'编辑'+pgTitle(id,key)+'提示词',subtitle,
  '<div class="aw-prompt-stages">'+defs.map(([k])=>B(pgTitle(id,k),'aw-prompt-tab',k===key?'soft':'ghost','data-stage="'+k+'"')).join('')+'</div>'+
  '<label class="field"><span>选择提示词</span>'+pgSelect(id,key,p.draft,'id="aw-prompt-template" data-pg-editor="'+key+'" '+(locked?'disabled':''))+'</label>'+
  '<div class="field aw-prompt-text">'+editorHeading+'<textarea id="prompt-editor" data-aw-draft="content" '+(locked?'readonly':'')+'>'+E(p.draft.content)+'</textarea></div>'+
  (p.pgPatches[key]?'<p class="pg-pending-note">应用时将更新'+E(pgImpact(id,key))+'，需确认后生效。</p>':'')+'<p id="aw-prompt-error" class="error" role="alert"></p>',
  locked?B('关闭','close-modal'):B('取消','close-modal')+B('另存个人提示词','aw-store-prompt')+B('应用提示词','aw-prompt-save','primary'),
  'aw-prompt-dialog pg-prompt-dialog'+(id==='theme'?' th-prompt-dialog':['meeting','risk'].includes(id)?' aa-prompt-dialog':''));
}
function pgCommitDraft(p){const task=currentTask(),id=state.toolId;if(task&&!p.secondary)return;if(!Object.values(p.drafts).filter(s=>s?.content!=null).every(s=>s.content.trim())){document.getElementById('aw-prompt-error').textContent='请填写提示词内容';return;}if(p.secondary){task.riskStageDraft=structuredClone(p.draft);}else{const c=ws().config;c.stages=structuredClone(p.drafts);for(const [key,related] of Object.entries(p.pgPatches||{}))pgApplyRelated(c,id,key,related);pgSync(c,id);}awBase.closeModal();render();toast('提示词已应用。');}
function pgSelectPrompt(id,key,value,editor=false){if(value==='current')return;const item=pgLibrary(id,key).find(i=>i.value===value);if(!item)return;if(currentTask()&&!(editor&&modalData.secondary))return;const stage=pgStageFrom(item,id,key);if(editor){const p=modalData;p.drafts[key]=stage;p.draft=stage;if(item.related)p.pgPatches[key]=structuredClone(item.related);else delete p.pgPatches[key];paintModal();}else if(item.related){openModal('pg-prompt-confirm',{kind:'selection',stage:key,item:structuredClone(item)});}else{const c=ws().config;c.stages[key]=stage;pgSync(c,id);render();}}
modalContent=function(){if(pgActive()&&modal==='aw-prompt'&&modalData.pg)return pgEditor(modalData);if(pgActive()&&modal==='aw-store-prompt'&&modalData.pg)return modalFrame('另存个人提示词','保存当前环节的提示词'+(pgImpact(state.toolId,modalData.stage)?'及配套规则。':'。'),'<label class="field"><span>提示词名称 <b class="red">*</b></span><input id="aw-scheme-name" maxlength="100" value="'+E(modalData.name)+'"></label><p id="aw-scheme-error" class="error" role="alert"></p>',B('取消','aw-store-back')+B('保存提示词','aw-store-confirm','primary'),'small');
 if(modal==='pg-prompt-confirm'){const p=modalData,keys=p.kind==='editor'?Object.keys(p.back.pgPatches):[p.stage];return modalFrame('确认切换提示词','所选提示词包含配套规则。','<p>将更新'+keys.map(k=>E(pgImpact(state.toolId,k))).join('、')+'。请确认后继续。</p><p class="pg-confirm-help">其余环节、已添加资料和任务记录保持不变。</p>',B('取消','close-modal')+B('确认切换','pg-confirm-prompt','primary'),'small');}
 return pgBase.modalContent();};
closeModal=function(){if(modal==='pg-prompt-confirm'&&modalData.kind==='editor'){const back=modalData.back;openModal('aw-prompt',back);return;}if(modal==='pg-prompt-confirm'&&modalData.kind==='selection'){pgBase.closeModal();render();return;}return pgBase.closeModal();};
handleAction=function(action,el){if(state.view==='tool'&&['pg-import-settings','pg-validate-settings','pg-apply-settings','aw-import-config','v2-export-config','ew-import','v2-template-import','v2-template-import-save'].includes(action))return;if(!pgActive())return pgBase.handleAction(action,el);const id=state.toolId,task=currentTask(),key=el?.dataset?.stage||pgDefs()[0]?.[0];
 if(['aw-prompt','v2-stage','prompt'].includes(action))return pgOpen(key);
 if(action==='aw-risk-prompt'&&id==='meeting')return pgOpen('risk',!!task);
 if(action==='aw-prompt-tab'&&modalData.pg){modalData.stage=key;modalData.draft=modalData.drafts[key];paintModal();return;}
 if(['aw-prompt-reset','v2-stage-reset'].includes(action)&&modalData.pg)return pgSelectPrompt(id,modalData.stage,'system',true);
 if(action==='aw-prompt-save'&&modalData.pg){const p=modalData;if(task&&!p.secondary)return;if(!Object.values(p.drafts).every(s=>s.content?.trim())){document.getElementById('aw-prompt-error').textContent='请填写提示词内容';return;}if(Object.keys(p.pgPatches||{}).length)return openModal('pg-prompt-confirm',{kind:'editor',back:structuredClone(p)});return pgCommitDraft(p);}
 if(action==='pg-confirm-prompt'&&!task){const p=modalData;if(p.kind==='editor')return pgCommitDraft(p.back);const c=ws().config;c.stages[p.stage]=pgStageFrom(p.item,id,p.stage);pgApplyRelated(c,id,p.stage,p.item.related);pgSync(c,id);awBase.closeModal();render();return;}
 if(action==='aw-store-prompt'&&modalData.pg){if(task&&!modalData.secondary)return;const back=structuredClone(modalData);if(!back.draft.content.trim()){document.getElementById('aw-prompt-error').textContent='请填写提示词内容';return;}openModal('aw-store-prompt',{pg:true,stage:back.stage,back:{type:'aw-prompt',data:back},name:back.draft.template+' · 我的版本'});return;}
 if(action==='aw-store-back'&&modalData.pg){openModal('aw-prompt',modalData.back.data);return;}
 if(action==='aw-store-confirm'&&modalData.pg){const p=modalData,name=document.getElementById('aw-scheme-name').value.trim(),stage=p.stage;if(!name||state.templates.some(t=>pgScope(t)==='personal'&&t.toolId===id&&t.stage===stage&&t.name===name)){document.getElementById('aw-scheme-error').textContent=name?'同名提示词已存在，请调整名称。':'请填写提示词名称。';return;}const back=p.back.data,c=structuredClone(task?.config||ws().config);c.stages=structuredClone(back.drafts);if(back.pgPatches[stage])pgApplyRelated(c,id,stage,back.pgPatches[stage]);const related=pgCaptureRelated(id,stage,c),record={id:'prompt-'+crypto.randomUUID(),kind:'prompt',scope:'personal',toolId:id,stage,functionType:PROMPT_STAGES[id].find(d=>d[0]===stage)[2],name,prompt:back.draft.content,...(related?{promptConfig:related}:{})};state.templates.push(record);back.draft.template=name;if(related)back.draft.promptConfig=structuredClone(related);back.draft.origin='personal';back.draft.scope='personal';back.draft.category='';back.draft.backendId=null;back.draft.customized=false;back.draft.pgChoice='p:'+record.id;persist();openModal('aw-prompt',back);toast('个人提示词已保存。');return;}
 if(['aw-save-scheme','save-template','v2-save-stage-template'].includes(action)){if(task)return;pgOpen(key);return;}
 if(['v4-reset-mapping','v2-hard-reset'].includes(action)&&id==='association'){const source=(task?.config||ws().config).stages.compare.promptConfig?.association||PG_ROOT_DEFAULTS.association.association;if(action==='v4-reset-mapping'){editorDraft.rows=structuredClone(source.rows);editorDraft.hardRules=structuredClone(source.hardRules);}else editorDraft.hardRules=structuredClone(source.hardRules);paintModal();toast('已恢复所选提示词的字段或规则，保存前可取消。');return;}
 return pgBase.handleAction(action,el);
};
mappingEditor=function(two){const root=document.createElement('div');root.innerHTML=pgBase.mappingEditor(two);if(state.toolId==='association'){const rows=root.querySelector('[data-action=v4-reset-mapping]'),rules=root.querySelector('[data-action=v2-hard-reset]');if(rows)rows.textContent='恢复提示词字段';if(rules)rules.textContent='恢复提示词规则';}return root.innerHTML;};
window.addEventListener('change',e=>{const el=e.target;if(!pgActive())return;if(el.dataset.pgPrompt){e.stopImmediatePropagation();return pgSelectPrompt(state.toolId,el.dataset.pgPrompt,el.value);}if(el.dataset.pgEditor){e.stopImmediatePropagation();return pgSelectPrompt(state.toolId,el.dataset.pgEditor,el.value,true);}},true);
window.addEventListener('input',e=>{if(pgActive()&&modal==='aw-prompt'&&modalData.pg&&e.target.id==='prompt-editor'&&(!currentTask()||modalData.secondary)){const s=modalData.draft;s.content=e.target.value;s.backendId=null;s.customized=true;s.pgChoice='current';const select=document.getElementById('aw-prompt-template');if(select){let option=select.querySelector('[value=current]');if(!option){option=document.createElement('option');option.value='current';select.prepend(option);}option.textContent=(s.template||'本次提示词')+' · 本次已调整';select.value='current';const source=select.nextElementSibling;if(source?.classList.contains('pg-source-path')&&!source.textContent.endsWith(' · 本次已调整'))source.textContent+=' · 本次已调整';}}},true);
render();
